'use strict';

// Build the OS icon files from the one brand mark. The mark itself is generated by
// studio/scripts/make_icons.py; this script only converts it for Electron.
const fs = require('fs');
const path = require('path');
const png2icons = require('png2icons');

const root = path.join(__dirname, '..');
const source = path.join(root, '..', 'assets', 'logo.png');
const build = path.join(root, 'build');
fs.mkdirSync(build, { recursive: true });

const png = fs.readFileSync(source);
fs.writeFileSync(path.join(build, 'icon.png'), png);

const ico = png2icons.createICO(png, png2icons.BICUBIC, 0, false);
const icns = png2icons.createICNS(png, png2icons.BICUBIC, 0);
if (!ico || !icns) throw new Error('could not render the icon container');
fs.writeFileSync(path.join(build, 'icon.ico'), ico);
fs.writeFileSync(path.join(build, 'icon.icns'), icns);
console.log(`icons: ${path.join(build, 'icon.ico')}, ${path.join(build, 'icon.icns')}`);
